export type Question={id:string;prompt:string;options:string[];correct:number;explanation:string};
export type Lesson={id:number;chapter:number;title:string;page:number;endPage:number;intro:string;sections:{title:string;text:string}[];points:string[];terms:{term:string;definition:string}[];questions:Question[];note:{kind:'ფაქტი'|'მითი'|'ვარაუდი'|'მასწავლებლის შესამოწმებელი';text:string};exercise:{prompt:string;answer:string};image:string;imageCaption:string};
export const chapters=[
{id:1,title:'ჩვენი სამშობლო — საქართველო',period:'სივრცე და ისტორია',color:'#3e7b73',pages:'8–19'},
{id:2,title:'რით ვსწავლობთ ძველ ისტორიას',period:'წარსულის მკვლევრები',color:'#b27a3f',pages:'20–35'},
{id:3,title:'ქვის ხანის ეპოქის ადამიანის თავგადასავალი',period:'ადამიანის პირველი ნაბიჯები',color:'#687e49',pages:'36–53'},
{id:4,title:'ქვიდან ლითონამდე',period:'ახალი აღმოჩენების ეპოქა',color:'#b56b4d',pages:'54–75'},
{id:5,title:'უძველესი ქართული სახელმწიფოები',period:'კოლხეთი და გარე სამყარო',color:'#556daa',pages:'76–97'},
{id:6,title:'პირველი ერთიანი ქართული სახელმწიფო',period:'ქართლის სამეფოს დაბადება',color:'#8662a8',pages:'98–123'}];
const lessons:Lesson[]=[];
function add(id:number,chapter:number,title:string,page:number,intro:string,sections:string[][],terms:string[][],qs:string[][],kind:Lesson['note']['kind']='ფაქტი',note='',exercise?:string[]){
 const questions=qs.map((q,i)=>{const shift=(id+i)%4;const raw=q.slice(1,5);const options=[...raw.slice(shift),...raw.slice(0,shift)];return {id:`${id}-${i+1}`,prompt:q[0],options,correct:(4-shift)%4,explanation:q[5]}});
 lessons.push({id,chapter,title,page,endPage:id===1?13:id===2?19:id===3?27:id===14?75:page+3,intro,sections:sections.map(s=>({title:s[0],text:s[1]})),terms:terms.map(t=>({term:t[0],definition:t[1]})),questions,points:qs.map(q=>q[5]),note:{kind,text:note||'ამ გაკვეთილში განვიხილავთ სახელმძღვანელოს ძირითად ტექსტზე დაყრდნობილ ცნობებს.'},exercise:{prompt:exercise?.[0]||'აირჩიე ორი მთავარი აზრი და საკუთარი სიტყვებით ახსენი, როგორ უკავშირდება ისინი ერთმანეთს.',answer:exercise?.[1]||qs[0][5]+' '+qs[1][5]},image:`/assets/page-${page===11?12:page}.webp`,imageCaption:`სახელმძღვანელოს შესაბამისი გვერდი — გვ. ${page===11?12:page}. ილუსტრაციები შეიძლება თანამედროვე რეკონსტრუქციასაც შეიცავდეს.`});
}
add(1,1,'საქართველოს გეოგრაფიული მდებარეობა',11,'ჩვენი მოგზაურობა რუკიდან იწყება: სად მდებარეობს საქართველო და როგორ ერქვა მას სხვადასხვა დროს?',[
['სად არის საქართველო?','საქართველო კავკასიის რეგიონში მდებარეობს. დასავლეთით მას შავი ზღვა აკრავს. ჩრდილოეთით რუსეთი, აღმოსავლეთით აზერბაიჯანი, სამხრეთით სომხეთი, სამხრეთ-დასავლეთით კი თურქეთი ესაზღვრება.'],
['ერთი ქვეყანა, სხვადასხვა სახელწოდება','ძველად დასავლეთ საქართველოს კოლხეთსა და ეგრისს უწოდებდნენ, აღმოსავლეთს კი — ქართლსა და იბერიას. ერთიანი ქვეყნის ჩამოყალიბებასთან ერთად გავრცელდა სახელწოდება „საქართველო“.'],
['გზების გადაკვეთაზე','საქართველოს მდებარეობა აღმოსავლეთსა და დასავლეთს შორის ურთიერთობას უწყობდა ხელს. გზებით გადაადგილდებოდნენ ვაჭრები, მოგზაურები და სხვადასხვა ხალხის წარმომადგენლები.']],
[['კავკასია','რეგიონი შავ და კასპიის ზღვებს შორის.'],['იბერია','აღმოსავლეთ საქართველოს ძველი სახელწოდება.'],['სატრანზიტო გზა','გზა, რომელიც ტერიტორიაზე გადის და სხვადასხვა მხარეს აკავშირებს.']],
[['რომელ რეგიონში მდებარეობს საქართველო?','კავკასიაში','სკანდინავიაში','პირენეის ნახევარკუნძულზე','ცენტრალურ აფრიკაში','საქართველო კავკასიის რეგიონში მდებარეობს.'],['რომელი ზღვა აკრავს საქართველოს დასავლეთით?','შავი ზღვა','კასპიის ზღვა','წითელი ზღვა','ბალტიის ზღვა','საქართველოს დასავლეთით შავი ზღვა აკრავს.'],['აღმოსავლეთ საქართველოს რომელი სახელი გვხვდება ძველ წყაროებში?','იბერია','გალია','თრაკია','ბაბილონი','ქართლი და იბერია აღმოსავლეთ საქართველოს სახელწოდებებია.'],['რომელი სახელი უკავშირდება დასავლეთ საქართველოს?','კოლხეთი','ბაქტრია','ასურეთი','პართია','დასავლეთ საქართველოს ძველად კოლხეთსა და ეგრისს უწოდებდნენ.'],['რას უწყობდა ხელს საქართველოს მდებარეობა?','აღმოსავლეთთან და დასავლეთთან კავშირს','ყველა მეზობლისგან სრულ მოწყვეტას','ზღვების გაქრობას','წელთაღრიცხვის შეწყვეტას','საქართველოს გავლით მიმავალი გზები აღმოსავლეთსა და დასავლეთს აკავშირებდა.']],
'ფაქტი','ისტორიული სახელწოდებები და ძველი საზღვრები თანამედროვე სახელმწიფოების საზღვრებს ყოველთვის არ ემთხვევა.',['რუკაზე მიუთითე საქართველოს დასავლეთი და დაასახელე იქ მდებარე ზღვა.','დასავლეთით შავი ზღვაა. რუკაზე მიმართულებების განსასაზღვრად გამოიყენე ჩრდილოეთის მაჩვენებელი.']);
add(2,1,'მოგზაურობა საქართველოს ისტორიულ-გეოგრაფიულ მხარეებში',14,'საქართველოს კუთხეების მრავალფეროვნებას ბუნება, საქმიანობა და საუკუნეების ისტორია ქმნის.',[
['ისტორიული მხარეები','საქართველო მრავალი ისტორიულ-გეოგრაფიული მხარისგან შედგება. მათ შორისაა ქართლი, კახეთი, იმერეთი, აჭარა, გურია, სამეგრელო, სვანეთი, აფხაზეთი და მესხეთის მხარეები.'],['მთა და ბარი','მთიანეთსა და ბარში განსხვავებული ბუნებრივი პირობებია. ეს გავლენას ახდენდა დასახლებაზე, საცხოვრებელზე და მეურნეობაზე. ამიტომ თითოეულ კუთხეს საკუთარი თავისებურებები ჩამოუყალიბდა.'],['მრავალფეროვნება და კავშირი','სხვადასხვა კუთხეს გზები, ვაჭრობა, კულტურა და საერთო ისტორია აკავშირებდა. ისტორიული მხარის საზღვარი თანამედროვე ადმინისტრაციულ საზღვარს ყოველთვის არ ემთხვევა.']],
[['ისტორიულ-გეოგრაფიული მხარე','საერთო ისტორიული და გეოგრაფიული ნიშნებით გამორჩეული ტერიტორია.'],['მეურნეობა','საქმიანობა, რომლითაც ადამიანები საჭირო პროდუქტებს ქმნიან.'],['ეთნოგრაფია','ხალხის ყოფის, ტრადიციებისა და კულტურის შემსწავლელი დარგი.']],
[['რომელი ჩამონათვალია საქართველოს ისტორიული მხარეების?','ქართლი, კახეთი, იმერეთი','ეგვიპტე, სირია, ბაქტრია','ათენი, რომი, სპარტა','ნილოსი, ტიგროსი, ევფრატი','ქართლი, კახეთი და იმერეთი საქართველოს ისტორიულ-გეოგრაფიული მხარეებია.'],['რა ახდენდა გავლენას მხარეების მეურნეობაზე?','ბუნებრივი პირობები','მხოლოდ სახელების სიგრძე','მხოლოდ კალენდარი','მხოლოდ მითები','ბუნებრივი პირობები გავლენას ახდენდა მოსახლეობის საქმიანობასა და დასახლებაზე.'],['რას სწავლობს ეთნოგრაფია?','ხალხის ყოფასა და ტრადიციებს','მხოლოდ მონეტების წონას','მხოლოდ წლების გამოთვლას','მხოლოდ ვარსკვლავებს','ეთნოგრაფია ხალხის ყოფასა და ტრადიციებს შეისწავლის.'],['რა აკავშირებდა საქართველოს კუთხეებს?','გზები, ვაჭრობა და კულტურა','მხოლოდ ერთმანეთისგან იზოლაცია','წერილობითი წყაროების გაქრობა','მდინარეების არარსებობა','საქართველოს მხარეებს ურთიერთობა, საერთო ისტორია და კულტურა აკავშირებდა.'],['როგორ უნდა შევადაროთ ისტორიული და თანამედროვე საზღვრები?','ისინი ყოველთვის არ ემთხვევა','ისინი ყოველთვის ზუსტად ერთია','ისტორიულ მხარეებს საზღვრები არ ჰქონია','თანამედროვე რუკა წარსულსაც უცვლელად ასახავს','ისტორიულ-გეოგრაფიული მხარეებისა და თანამედროვე ადმინისტრაციული ერთეულების საზღვრები შეიძლება განსხვავდებოდეს.']],
'ფაქტი','ისტორიული მხარეების რუკა იხილე წიგნის 125-ე გვერდზეც.',['აირჩიე შენი მხარე და აღწერე ერთი ბუნებრივი და ერთი კულტურული თავისებურება.','მაგალითად, აჭარა: შავი ზღვის სანაპირო და მთიანი ადგილები; ადგილობრივი არქიტექტურა და ტრადიციები.']);
add(3,2,'ქრონოლოგია',22,'ისტორიაში მხოლოდ „რა მოხდა?“ კი არა, „როდის მოხდა?“ კითხვაც მნიშვნელოვანია.',[
['წარსულის დალაგება','ქრონოლოგია დროსა და მოვლენათა თანმიმდევრობას შეისწავლის. ისტორიის პერიოდებად დაყოფა გვეხმარება დიდი ცვლილებების დანახვაში: ქვის ხანას ლითონების გამოყენების ეპოქები მოჰყვა.'],['წლები და საუკუნეები','ერთი საუკუნე 100 წელს მოიცავს, ათასწლეული — 1000 წელს. მაგალითად, ახ. წ. I საუკუნე 1–100 წლებს მოიცავს. საუკუნის გამოსათვლელად წლიდან ერთი გამოაკელი, 100-ზე გაყავი, მთელი ნაწილი აიღე და ერთი დაუმატე.'],['ძველი და ახალი წელთაღრიცხვა','ძვ. წ. თარიღებში დიდი რიცხვი უფრო ძველ მოვლენას აღნიშნავს: ძვ. წ. 500 წელი ძვ. წ. 300 წელზე ადრეა. ახ. წ. წლებში რიცხვები წინსვლისას იზრდება. ისტორიულ წელთაღრიცხვაში ნულოვანი წელი არ არის.']],
[['ქრონოლოგია','დროისა და მოვლენათა თანმიმდევრობის შესწავლა.'],['საუკუნე','ასი წლის პერიოდი.'],['ერა','წელთაღრიცხვის საწყის მოვლენასთან დაკავშირებული ათვლის სისტემა.']],
[['რას შეისწავლის ქრონოლოგია?','დროსა და მოვლენათა თანმიმდევრობას','მხოლოდ მცენარეთა ჯიშებს','მხოლოდ სამკაულს','მხოლოდ შენობებს','ქრონოლოგია გვეხმარება მოვლენების დროში დალაგებაში.'],['რამდენი წელია ერთ საუკუნეში?','100','10','1000','50','ერთი საუკუნე 100 წელს მოიცავს.'],['რომელი თარიღია უფრო ძველი?','ძვ. წ. 500 წელი','ძვ. წ. 300 წელი','ახ. წ. 100 წელი','ახ. წ. 500 წელი','ძვ. წ. თარიღებში უფრო დიდი რიცხვი უფრო ძველ დროს აღნიშნავს.'],['რომელ საუკუნეში შედის ახ. წ. 101 წელი?','II საუკუნეში','I საუკუნეში','X საუკუნეში','XI საუკუნეში','ახ. წ. II საუკუნე 101–200 წლებს მოიცავს.'],['რომელი ცვლილება გამოყოფს ისტორიულ ხანას წინარეისტორიულისგან?','დამწერლობის გაჩენა','ზღვის გაქრობა','საუკუნის 10 წლად ქცევა','ქვის არსებობა','ისტორიულ და წინარეისტორიულ ხანებს შორის მნიშვნელოვანი გამყოფი ნიშანია დამწერლობის გაჩენა.']],
'ფაქტი','ეპოქების საზღვრები პირობითია და სხვადასხვა რეგიონში ცვლილებები ერთდროულად არ ხდებოდა.',['დაალაგე: ახ. წ. 200, ძვ. წ. 100, ძვ. წ. 500.','ძვ. წ. 500 → ძვ. წ. 100 → ახ. წ. 200.']);
add(4,2,'მიწაში დამარხული ისტორია',28,'ნივთებს ლაპარაკი არ შეუძლიათ, მაგრამ არქეოლოგები მათგან წარსულის შესახებ ბევრ რამეს იგებენ.',[
['ნივთიერი კვალი','არქეოლოგია ადამიანის წარსულს ნივთიერი ნაშთებით სწავლობს. ეს შეიძლება იყოს იარაღი, ჭურჭელი, სამკაული, სამარხი ან შენობის ნანგრევი.'],['აღმოჩენის გარემო','მნიშვნელოვანია არა მხოლოდ ნაპოვნი საგანი, არამედ მისი მდებარეობა და გარემოც. ნივთის თვითნებური ამოღებით შეიძლება დაიკარგოს ინფორმაცია, რომელიც მეცნიერისთვის აუცილებელია.'],['ერთობლივი კვლევა','არქეოლოგები თანამშრომლობენ სხვა დარგების მეცნიერებთან. ძვლების, მცენარეთა მტვრისა და საკვების ნაშთების კვლევა გვიჩვენებს ადამიანთა ცხოვრების პირობებსა და საქმიანობას.']],
[['არქეოლოგია','წარსულის ნივთიერი ნაშთების შემსწავლელი მეცნიერება.'],['არტეფაქტი','ადამიანის მიერ შექმნილი ან დამუშავებული საგანი.'],['ნამოსახლარი','ადგილი, სადაც წარსულში ადამიანები ცხოვრობდნენ.']],
[['რას შეისწავლის არქეოლოგია?','წარსულის ნივთიერ ნაშთებს','მხოლოდ მომავალს','მხოლოდ ამინდს','მხოლოდ ზეპირ ზღაპრებს','არქეოლოგია წარსულს ნივთიერი ნაშთების დახმარებით სწავლობს.'],['რომელია არტეფაქტი?','ადამიანის დამზადებული თიხის ჭურჭელი','დაუმუშავებელი ღრუბელი','წვიმის წვეთი','მზის სხივი','არტეფაქტია ადამიანის მიერ შექმნილი ან დამუშავებული ნივთი.'],['რატომ არის ნივთის აღმოჩენის ადგილი მნიშვნელოვანი?','ის საგნის გარემოსა და დროს გვაცნობინებს','ნივთი მხოლოდ ფერით ფასდება','მდებარეობას მნიშვნელობა არ აქვს','ყველა ფენა ერთდროულია','აღმოჩენის გარემო ნივთის მნიშვნელობისა და ასაკის გარკვევაში გვეხმარება.'],['რას გვამცნობს ჭურჭელში დარჩენილი მარცვლეული?','კვებისა და მეურნეობის შესახებ','მხოლოდ მეფის სახელს','მხოლოდ წელიწადის დღეს','მხოლოდ ქალაქის კანონებს','მცენარეული ნაშთები კვებისა და მეურნეობის შესწავლის წყაროა.'],['რა არის ნამოსახლარი?','ძველი საცხოვრებელი ადგილი','მხოლოდ თანამედროვე სკოლა','ნებისმიერი მდინარე','ვარსკვლავთა ჯგუფი','ნამოსახლარი წარსულში ადამიანთა დასახლების ადგილია.']]);
add(5,2,'წერილობითი წყაროები',32,'ქვაზე ამოკვეთილი წარწერა და მატიანე ორივე წყაროა, თუმცა მათი ცნობები შემოწმებას საჭიროებს.',[
['წარსული ტექსტებში','ისტორიკოსები იყენებენ წარწერებს, საბუთებს, მატიანეებსა და სხვა წერილობით ცნობებს. საქართველოს ისტორიისთვის მნიშვნელოვანია როგორც ქართული, ისე უცხოური წყაროები.'],['ეპიგრაფიკა','ეპიგრაფიკა მყარ მასალაზე შესრულებულ წარწერებს სწავლობს. საქართველოში აღმოჩენილია სხვადასხვა ენაზე შესრულებული წარწერები, მათ შორის ბერძნული და არამეული.'],['როგორ ვკითხულობთ წყაროს?','უნდა გავარკვიოთ, ვინ დაწერა ტექსტი, როდის და რა მიზნით. ავტორს შეიძლება საკუთარი შეხედულება ჰქონდეს ან მოვლენიდან დიდი ხნის შემდეგ წერდეს. ამიტომ ცნობებს ერთმანეთს და არქეოლოგიურ მასალას ვადარებთ.']],
[['ეპიგრაფიკა','ქვაზე, ლითონსა და სხვა მყარ მასალაზე წარწერების შესწავლა.'],['მატიანე','ისტორიული ამბების აღმწერი თხზულება.'],['ბილინგვა','ორ ენაზე შესრულებული წარწერა.']],
[['რას სწავლობს ეპიგრაფიკა?','მყარ მასალაზე შესრულებულ წარწერებს','მხოლოდ მიწის ფენებს','მხოლოდ მცენარეებს','მხოლოდ ქარის მიმართულებას','ეპიგრაფიკა მყარ მასალაზე შესრულებულ წარწერებს შეისწავლის.'],['რას ნიშნავს ბილინგვა?','ორენოვან წარწერას','ოქროს მონეტას','სამეფო სასახლეს','ქვის იარაღს','ბილინგვა ორ ენაზე შესრულებული წარწერაა.'],['რომელია ქართული საისტორიო თხზულება?','ქართლის ცხოვრება','არგოს აფრა','თრიალეთის თასი','კოლხური ცული','„ქართლის ცხოვრება“ ქართული საისტორიო თხზულებების კრებულია.'],['რატომ ვადარებთ სხვადასხვა წყაროს?','ცნობების შესამოწმებლად','ყველა განსხვავების დასამალად','თარიღების წასაშლელად','მხოლოდ ტექსტის გასაგრძელებლად','სხვადასხვა წყაროს შედარება ცნობების სანდოობის შეფასებაში გვეხმარება.'],['რა უნდა გავარკვიოთ წყაროს კითხვისას?','ავტორი, დრო და დაწერის მიზანი','მხოლოდ ასოების ფერი','მხოლოდ გვერდის ზომა','მხოლოდ სათაურის სიგრძე','წყაროს გასაგებად მნიშვნელოვანია ავტორის, დროისა და მიზნის ცოდნა.']],
'მასწავლებლის შესამოწმებელი','წიგნში ბოლნისის წარწერის თარიღად ძირითად ტექსტში 493–494 წლებია მოცემული, ილუსტრაციის განმარტება კი განსხვავებულ მოსაზრებასაც ახსენებს. ეს საკითხი ქვიზში ერთმნიშვნელოვან თარიღად არ არის შეტანილი.');
add(6,3,'უძველესი ადამიანის ნაკვალევი დმანისიდან',38,'დმანისში აღმოჩენილმა ნაშთებმა აფრიკიდან ევრაზიაში ადამიანის უძველესი გავრცელების კვლევა შეცვალა.',[
['აღმოჩენა ქალაქის ქვეშ','დმანისში მეცნიერები შუა საუკუნეების ქალაქს იკვლევდნენ. მის ქვეშ უძველესი ცხოველების ნაშთები და ქვის იარაღები აღმოაჩინეს.'],['1,8 მილიონი წლის კვალი','1991 წელს დმანისში ჰომინინის ქვედა ყბა იპოვეს. ნაშთების შემცველი ფენები დაახლოებით 1,8 მილიონი წლით თარიღდება. მოგვიანებით თავის ქალებიც აღმოაჩინეს.'],['რატომ არის ეს მნიშვნელოვანი?','დმანისის მასალა აფრიკის გარეთ ადრეული ჰომინინების არსებობის მნიშვნელოვანი მტკიცებულებაა. ის გვეხმარება მიგრაციისა და ადამიანის ევოლუციის შესწავლაში.']],
[['ჰომინინი','ადამიანი და მისი გადაშენებული ახლო ნათესავები ადამიანის ევოლუციურ ხაზში.'],['მიგრაცია','ერთი ადგილიდან მეორეში გადაადგილება და განსახლება.'],['ევოლუცია','ცოცხალი ორგანიზმების ცვლილება თაობათა განმავლობაში.']],
[['სად აღმოაჩინეს გაკვეთილში განხილული უძველესი ნაშთები?','დმანისში','ათენში','რომში','მცხეთაში','დმანისი ქვემო ქართლში მდებარე მნიშვნელოვანი არქეოლოგიური ძეგლია.'],['რა აღმოაჩინეს დმანისში 1991 წელს?','ჰომინინის ქვედა ყბა','ქაღალდის მატიანე','რკინიგზის ნაწილი','ბერძნული თეატრი','1991 წლის აღმოჩენა ჰომინინის ქვედა ყბა იყო.'],['დაახლოებით რა ასაკისაა დმანისის ჰომინინების ფენები?','1,8 მილიონი წლის','180 წლის','1800 წლის','18 ათასი წლის','დმანისის ჰომინინების ნაშთები დაახლოებით 1,8 მილიონი წლით თარიღდება.'],['რომელ პროცესს გვაგებინებს დმანისის აღმოჩენა?','აფრიკიდან ევრაზიაში ჰომინინების გავრცელებას','მხოლოდ შუა საუკუნეების ვაჭრობას','მხოლოდ ქაღალდის შექმნას','მხოლოდ მონეტის მოჭრას','დმანისის მასალა აფრიკის გარეთ ადრეული გავრცელების შესწავლისთვის მნიშვნელოვანია.'],['რას იკვლევდნენ თავდაპირველად დმანისში?','შუა საუკუნეების ქალაქს','თანამედროვე აეროპორტს','ბერძნულ ფლოტს','ეგვიპტის პირამიდას','უძველესი ნაშთები შუა საუკუნეების ქალაქის ქვემოთ გამოვლინდა.']],
'მასწავლებლის შესამოწმებელი','დმანისის ჰომინინების სახეობრივი სახელწოდება სამეცნიერო განხილვის საგანია. აქ არ ვასწავლით, რომ მათგან თანამედროვე ქართველი ერი პირდაპირ წარმოიშვა.');
add(7,3,'ქვის ხანა საქართველოში',42,'ქვის ხანაში ადამიანებმა იარაღი, საცხოვრებელი და ბუნებასთან შეგუების გზები თანდათან განავითარეს.',[
['სამი დიდი პერიოდი','ქვის ხანა პალეოლითად, მეზოლითად და ნეოლითად იყოფა. ეს სახელები შესაბამისად ძველ, შუა და ახალ ქვის ხანას ნიშნავს.'],['ცხოვრება პალეოლითში','ადამიანები ნადირობდნენ, თევზაობდნენ და საკვებ მცენარეებს აგროვებდნენ. იარაღს ამზადებდნენ ქვისგან, ძვლისგან და ხისგან. კაჟისა და ობსიდიანის იარაღები უკეთ შემოინახა.'],['გარემო და ცვლილება','კლიმატის ცვლილება დასახლებაზე მოქმედებდა. დათბობის შემდეგ ადამიანებმა ახალი ადგილები აითვისეს და თანდათან უფრო მრავალფეროვანი იარაღები შექმნეს.']],
[['პალეოლითი','ძველი ქვის ხანა.'],['მეზოლითი','შუა ქვის ხანა.'],['ობსიდიანი','ვულკანური მინა, რომელსაც იარაღისთვის იყენებდნენ.']],
[['რომელი თანმიმდევრობაა სწორი?','პალეოლითი, მეზოლითი, ნეოლითი','ნეოლითი, პალეოლითი, მეზოლითი','მეზოლითი, ნეოლითი, პალეოლითი','ნეოლითი, მეზოლითი, პალეოლითი','ქვის ხანის ძირითადი ეტაპებია პალეოლითი, მეზოლითი და ნეოლითი.'],['რას ნიშნავს პალეოლითი?','ძველ ქვის ხანას','რკინის ხანას','შუა საუკუნეებს','ბრინჯაოს ხანას','პალეოლითი ძველი ქვის ხანაა.'],['რა არის ობსიდიანი?','ვულკანური მინა','დამწვარი ხე','ოქროს შენადნობი','ნაქსოვი ქსოვილი','ობსიდიანი ვულკანური მინაა და ქვის იარაღის დასამზადებლად გამოიყენებოდა.'],['როგორ მოიპოვებდნენ საკვებს პალეოლითში?','ნადირობითა და შემგროვებლობით','ქარხნული წარმოებით','სუპერმარკეტიდან','მონეტის ბეჭდვით','პალეოლითის მოსახლეობის ძირითად საქმიანობას ნადირობა და შემგროვებლობა წარმოადგენდა.'],['რა მოქმედებდა საცხოვრებელი ადგილის არჩევაზე?','კლიმატი და საკვების ხელმისაწვდომობა','მხოლოდ მონეტების ფერი','მხოლოდ წერილების ზომა','მხოლოდ მეფის გვირგვინი','ბუნებრივი გარემო და საკვების რესურსები დასახლების ადგილის არჩევაზე მოქმედებდა.']],
'მასწავლებლის შესამოწმებელი','წიგნის ზედა პალეოლითის თარიღები საქართველოში აღმოჩენილ ძეგლებს ეხება. ჰომო საპიენსის წარმოშობა მხოლოდ 40 ათასი წლის წინ მომხდარ მოვლენად არ უნდა გავიგოთ.');
add(8,3,'ნეოლითური რევოლუცია',46,'ადამიანმა საკვების მხოლოდ მოპოვებიდან მისი წარმოება დაიწყო — ეს ცხოვრების დიდი გარდატეხა იყო.',[
['მოყვანა და მოშინაურება','ნეოლითში ადამიანები მიწას ამუშავებდნენ, მცენარეებს თესავდნენ და ცხოველებს აშინაურებდნენ. საკვების წარმოება თანდათან უფრო მნიშვნელოვან საქმიანობად იქცა.'],['მუდმივი დასახლებები','ნათესის მოვლა ხანგრძლივად ერთ ადგილზე ცხოვრებას მოითხოვდა. სახლებს, მარაგის შესანახ ადგილებსა და სამუშაო იარაღებს ახალი დანიშნულება მიეცა.'],['ახალი უნარები','გავრცელდა თიხის ჭურჭელი, ქვის გახეხვა-გაპრიალება, ქსოვა და სხვა ხელობები. „რევოლუცია“ აქ ხანგრძლივ, მაგრამ ძირეულ ცვლილებას ნიშნავს.']],
[['ნეოლითი','ახალი ქვის ხანა.'],['მწარმოებლური მეურნეობა','მეურნეობა, როცა ადამიანი საკვებს თვითონ აწარმოებს.'],['მოშინაურება','ველური ცხოველების ადამიანის მეურნეობასთან შეგუების ხანგრძლივი პროცესი.']],
[['რა არის ნეოლითური რევოლუციის მთავარი ცვლილება?','საკვების წარმოებაზე გადასვლა','საკვების სრულად შეწყვეტა','დამწერლობის გაქრობა','ქალაქების ჰაერში გადატანა','ნეოლითური რევოლუცია მიწათმოქმედებასა და მეცხოველეობაზე გადასვლას უკავშირდება.'],['რომელია მწარმოებლური საქმიანობა?','ხორბლის მოყვანა','ველური ნაყოფის შეგროვება','მხოლოდ ნადირობა','მხოლოდ ველური თევზის დაჭერა','მიწათმოქმედებისას ადამიანი მცენარეს თვითონ ზრდის და მოსავალს იღებს.'],['რატომ გახდა ერთ ადგილზე ცხოვრება მნიშვნელოვანი?','ნათესისა და პირუტყვის მოსავლელად','ზღვის დასაშრობად','ყველა იარაღის დასავიწყებლად','დროის გასაჩერებლად','ნათესისა და შინაური ცხოველების მოვლა მუდმივ საქმიანობას მოითხოვდა.'],['რომელი ხელობა განვითარდა ნეოლითში?','მეთუნეობა','მხოლოდ წიგნის ბეჭდვა','ავტომობილების აწყობა','რკინიგზის მშენებლობა','ნეოლითში განვითარდა თიხის ჭურჭლის დამზადება — მეთუნეობა.'],['რას ნიშნავს აქ სიტყვა „რევოლუცია“?','ცხოვრების ძირეულ ცვლილებას','მხოლოდ ერთდღიან ბრძოლას','ქვის სხვა სახელს','მდინარის დინებას','ნეოლითური რევოლუცია ხანგრძლივ, მაგრამ ძირეულ სამეურნეო ცვლილებას აღნიშნავს.']]);
add(9,3,'ხორბლისა და ღვინის უძველესი კერები საქართველოში',50,'ქვემო ქართლის ნამოსახლარებმა უძველესი მიწათმოქმედებისა და ღვინის წარმოების მნიშვნელოვანი კვალი შემოგვინახა.',[
['რას პოულობენ მეცნიერები?','ნეოლითურ ნამოსახლარებში აღმოჩენილია თოხები, ნამგლები, საფქვავები და მარცვლეული. ეს მასალა მიწათმოქმედებაზე მიუთითებს.'],['ხორბლის მრავალფეროვნება','ხორბლის ველური და კულტურული ფორმების კვლევა გვიჩვენებს, როგორ არჩევდნენ ადამიანები სასარგებლო მცენარეებს. კულტურული ჯიშები ხანგრძლივი შერჩევის შედეგად მიიღებოდა.'],['ღვინის უძველესი კვალი','ქვემო ქართლში აღმოჩენილ თიხის ჭურჭელში ღვინის წარმოების უძველესი მტკიცებულებებია გამოვლენილი. წიგნი ამ ტრადიციას დაახლოებით 8 ათასი წლის ისტორიას უკავშირებს.']],
[['სელექცია','მცენარეთა და ცხოველთა სასურველი თვისებების შერჩევა და ახალი ჯიშების გამოყვანა.'],['ენდემური','კონკრეტული ტერიტორიისთვის დამახასიათებელი სახეობა.'],['საწნახელი','ყურძნის დასაწურად მოწყობილი ადგილი ან ჭურჭელი.']],
[['რომელი ნივთი მიანიშნებს მარცვლეულის დამუშავებაზე?','საფქვავი','გვირგვინი','მშვილდის სიმი','საბრძოლო ეტლი','საფქვავები მარცვლეულის დამუშავების მტკიცებულებაა.'],['საქართველოს რომელ მხარეს უკავშირდება გაკვეთილში განხილული ნეოლითური აღმოჩენები?','ქვემო ქართლს','მხოლოდ სვანეთის მწვერვალებს','მხოლოდ შავი ზღვის ფსკერს','მხოლოდ აფრიკას','ქვემო ქართლის ნამოსახლარები ადრეული მიწათმოქმედებისა და ღვინის კვლევისთვის მნიშვნელოვანია.'],['დაახლოებით რამდენი წლის ღვინის წარმოების კვალს განიხილავს წიგნი?','8 ათასი წლის','80 წლის','800 წლის','8 მილიონი წლის','წიგნში განხილული ღვინის უძველესი მტკიცებულებები დაახლოებით 8 ათასი წლისაა.'],['რას ნიშნავს სელექცია?','სასურველი თვისებების შერჩევასა და ჯიშების გამოყვანას','ქალაქის კედლის აგებას','წარწერის წაშლას','მხოლოდ თარიღის ჩაწერას','სელექცია მცენარეთა და ცხოველთა სასურველი თვისებების შერჩევას უკავშირდება.'],['რისთვის გამოიყენება საწნახელი?','ყურძნის დასაწურად','რკინის გამოსადნობად','მონეტის მოსაჭრელად','ქვის იარაღის სათლელად','საწნახელში ყურძენს წურავდნენ და წვენს იღებდნენ.']],
'მასწავლებლის შესამოწმებელი','წიგნის 52-ე გვერდზე საერთაშორისო ორგანიზაციის სახელწოდება ტექსტურ ამონაწერში ვერ იკითხება. ეს ცნობა ქვიზში არ არის გამოყენებული. „ყველაზე ძველი აღმოჩენა“ არ ნიშნავს, რომ სხვა მხარეებში ასეთი საქმიანობა შეუძლებელი იყო.');
add(10,4,'ადრე ბრინჯაოს ხანა საქართველოში — მტკვარ-არაქსის კულტურა',56,'ლითონების შერევით უფრო გამოსადეგი მასალა მიიღეს. ახალმა ტექნოლოგიამ შრომა და ხელოსნობა შეცვალა.',[
['რატომ ბრინჯაო?','სუფთა სპილენძი შედარებით რბილია. სხვა ნივთიერებებთან შერევით მიიღებოდა უფრო მტკიცე შენადნობი — ბრინჯაო. მისგან სამეურნეო და საბრძოლო იარაღებს ამზადებდნენ.'],['მტკვარსა და არაქსს შორის','ადრე ბრინჯაოს ხანის კულტურას მტკვარ-არაქსის კულტურას უწოდებენ. მისთვის დამახასიათებელია შავპრიალა კერამიკა, საცხოვრებელი სახლების სხვადასხვა ფორმა და განვითარებული ხელოსნობა.'],['ურთიერთობა ფართოვდება','მოსახლეობა მიწათმოქმედებასა და მეცხოველეობას მისდევდა. ლითონისა და სხვა ნაწარმის გაცვლა სხვადასხვა მხარეს შორის კავშირებს აძლიერებდა.']],
[['ბრინჯაო','სპილენძის შენადნობი სხვა ელემენტებთან.'],['კერამიკა','თიხისგან დამზადებული და გამომწვარი ნაწარმი.'],['მეტალურგია','მადნიდან ლითონის მიღება და დამუშავება.']],
[['რას წარმოადგენს ბრინჯაო?','სპილენძის შენადნობს','მხოლოდ სუფთა ოქროს','ვულკანურ მინას','ხის სახეობას','ბრინჯაო სპილენძის სხვა ელემენტებთან შერევით მიიღება.'],['რომელ ეპოქას უკავშირდება მტკვარ-არაქსის კულტურა?','ადრე ბრინჯაოს ხანას','ახალ ისტორიას','მხოლოდ შუა საუკუნეებს','თანამედროვეობას','მტკვარ-არაქსის კულტურა ადრე ბრინჯაოს ხანას უკავშირდება.'],['რომელი ჭურჭელია მისთვის დამახასიათებელი?','შავპრიალა თიხის ჭურჭელი','პლასტმასის ბოთლი','ქაღალდის ჭიქა','ფოლადის კონტეინერი','შავპრიალა კერამიკა მტკვარ-არაქსის კულტურის ერთ-ერთი დამახასიათებელი ნიშანია.'],['რისგან წარმოიშვა კულტურის სახელი?','მტკვრისა და არაქსის სახელებიდან','ორი მეფის სახელიდან','ორი წიგნის სახელიდან','ორი ბრძოლის სახელიდან','კულტურას სახელი მტკვრისა და არაქსის არეალის მიხედვით ეწოდა.'],['რა სარგებელი ჰქონდა უფრო მტკიცე იარაღს?','შრომის ეფექტიანობის ზრდა','მეურნეობის სრული გაქრობა','მიწის დამუშავების აკრძალვა','დასახლებების აუცილებელი დაცლა','უფრო მტკიცე ლითონის იარაღი სამეურნეო საქმიანობას ამარტივებდა.']]);
add(11,4,'შუა ბრინჯაოს ხანა — „თრიალეთის დიდი ყორღანების ბრწყინვალე კულტურა“',60,'დიდ სამარხებში შემონახული ნივთები ხელოსნობასა და საზოგადოების განსხვავებებზე მოგვითხრობს.',[
['ყორღანების ეპოქა','შუა ბრინჯაოს ხანას განსაკუთრებით დიდი ყორღანული სამარხებით ვსწავლობთ. თრიალეთში აღმოჩენილი ძეგლების გამო ამ კულტურას თრიალეთის კულტურას უწოდებენ.'],['რას გვიჩვენებს სამარხი?','ყორღანი სამარხზე აღმართული მიწისა და ქვის გორაკია. ზოგიერთში აღმოჩენილი ძვირფასი ნივთები და დიდი ნაგებობები საზოგადოების შიგნით განსხვავებულ მდგომარეობაზე მიანიშნებს.'],['მაღალი ხელოსნობა','გამოირჩევა ოქრომჭედლობა, ლითონის ჭურჭელი და კერამიკა. ნივთების დამზადება ცოდნას, დროსა და სხვადასხვა ოსტატის მუშაობას მოითხოვდა.']],
[['ყორღანი','სამარხზე აღმართული მიწისა და ქვის გორაკი.'],['ოქრომჭედლობა','ოქროს ნივთების დამზადების ხელობა.'],['სოციალური განსხვავება','საზოგადოებაში ადამიანთა მდგომარეობის, უფლებებისა და ქონების განსხვავება.']],
[['რომელ ეპოქას უკავშირდება თრიალეთის დიდი ყორღანები?','შუა ბრინჯაოს ხანას','მხოლოდ პალეოლითს','თანამედროვე ეპოქას','მხოლოდ შუა საუკუნეებს','თრიალეთის დიდი ყორღანები შუა ბრინჯაოს ხანის შესწავლის მნიშვნელოვანი წყაროა.'],['რა არის ყორღანი?','სამარხზე აღმართული გორაკი','სარწყავი არხი','მდინარის ნაპირი','ქაღალდის მატიანე','ყორღანი მიწისა და ქვის გორაკით დაფარული სამარხია.'],['რას მიანიშნებს ზოგი სამარხის განსაკუთრებული სიმდიდრე?','საზოგადოებაში განსხვავებულ მდგომარეობას','ყველა ნივთის ერთნაირობას','ხელოსნობის არარსებობას','მხოლოდ კლიმატის ცვლილებას','სამარხების განსხვავებული სიმდიდრე სოციალურ განსხვავებებზე მსჯელობის საფუძველია.'],['რომელი ხელობა გამოირჩეოდა თრიალეთის კულტურაში?','ოქრომჭედლობა','ავტომშენებლობა','ბეჭდვითი გაზეთების წარმოება','კომპიუტერის აწყობა','თრიალეთის აღმოჩენები ოქრომჭედლობის მაღალ დონეს გვიჩვენებს.'],['რის მიხედვით ეწოდა კულტურას სახელი?','თრიალეთში აღმოჩენილი ძეგლების მიხედვით','რომის სახელის მიხედვით','მხოლოდ მეფის გვარის მიხედვით','მითიური გემის მიხედვით','კულტურის სახელწოდება თრიალეთში გამოვლენილ ყორღანებს უკავშირდება.']]);
add(12,4,'გვიანი ბრინჯაოსა და ადრე რკინის ხანა',64,'ლითონის ახალი ტექნოლოგიები, ვაჭრობა და სპეციალიზებული ხელობები საზოგადოებას ცვლიდა.',[
['მრავალფეროვანი ხელობები','გვიანი ბრინჯაოს ხანაში განვითარდა მეთუნეობა, მეტალურგია, მშენებლობა და ვაჭრობა. დასავლეთსა და აღმოსავლეთში გამორჩეული კულტურული კერები არსებობდა.'],['ცხენი და გზები','ცხენს სამეურნეო საქმიანობაში, მგზავრობასა და ბრძოლაში იყენებდნენ. ცხენითა და ეტლით გადაადგილება შორეულ მხარეებს შორის კავშირს აადვილებდა.'],['რკინის ათვისება','რკინის დამუშავების ცოდნამ უფრო მტკიცე იარაღების გავრცელებას შეუწყო ხელი. ახალი ტექნოლოგია მჭედლების გამოცდილებასა და შრომის ორგანიზებას მოითხოვდა.']],
[['მჭედელი','ლითონის დამუშავების ოსტატი.'],['ეტლი','ბორბლებიანი სატრანსპორტო საშუალება.'],['სპეციალიზაცია','კონკრეტულ საქმიანობაში დაოსტატება.']],
[['რომელი საქმიანობა განვითარდა გვიან ბრინჯაოს ხანაში?','ხელოსნობა და ვაჭრობა','მხოლოდ წიგნის ბეჭდვა','კოსმოსური ფრენა','რკინიგზის მართვა','გვიან ბრინჯაოს ხანაში ხელოსნობა და ვაჭრობა ვითარდებოდა.'],['რას უწყობდა ხელს ცხენის გამოყენება?','შორეულ მხარეებს შორის გადაადგილებას','გზების საჭიროების გაქრობას','ყველა დასახლების დაცლას','ლითონის გაქრობას','ცხენი გადაადგილებასა და სხვადასხვა მხარეს შორის ურთიერთობას ამარტივებდა.'],['ვინ ამუშავებს ლითონს?','მჭედელი','მემატიანე','გეოგრაფი','მთარგმნელი','მჭედელი ლითონის დამუშავების ოსტატია.'],['რა მნიშვნელობა ჰქონდა რკინის დამუშავებას?','მტკიცე იარაღების წარმოება','საკვების მოყვანის შეუძლებლობა','ყოველი სხვა ნივთის აკრძალვა','წელთაღრიცხვის შეცვლა','რკინის ათვისება სამეურნეო და საბრძოლო იარაღების განვითარებას უწყობდა ხელს.'],['რას ნიშნავს სპეციალიზაცია?','ერთ საქმიანობაში დაოსტატებას','ყველა ხელობის გაქრობას','მხოლოდ მოგზაურობას','მხოლოდ მონადირეობას','ხელოსნები კონკრეტულ საქმიანობაში ოსტატდებოდნენ.']],
'ვარაუდი','ხალიბების ქართველურ ტომად მიჩნევა მეცნიერთა ნაწილის მოსაზრებაა. ეს ცნობა უპირობო ფაქტად არ არის შეტანილი ქვიზში.');
add(13,4,'ციკლოპური ციხე-ქალაქები',68,'რატომ ეწოდა უზარმაზარი ქვებით აგებულ ციხეებს მითიური ბუმბერაზების სახელი?',[
['დიდი ქვების მშენებლობა','ციკლოპური, ანუ მეგალითური ნაგებობები დიდი ზომის ლოდებითაა აგებული. ასეთი სიმაგრეები განსაკუთრებით სამხრეთ საქართველოში გვხვდება.'],['ციხე და ქალაქი','გამაგრებული ცენტრები მოსახლეობას, გზებსა და სამეურნეო სივრცეს იცავდა. ქალაქის ყველაზე მტკიცედ დაცულ ნაწილს ციტადელი ეწოდებოდა.'],['მითი და რეალური მშენებლები','ძველ ადამიანებს უზარმაზარი კედლები ზოგჯერ მითიური ბუმბერაზების აშენებული ეგონათ. ეს წარმოდგენა ნაგებობის დასახელებაში შემორჩა და ისტორიულ მტკიცებულებას არ წარმოადგენს.']],
[['მეგალითი','დიდი ქვა; მეგალითური ნაგებობა დიდი ქვებითაა აგებული.'],['ციტადელი','ქალაქის ყველაზე გამაგრებული ნაწილი — დედაციხე.'],['ციკლოპი','ძველბერძნული მითების ბუმბერაზი არსება.']],
[['რით შენდებოდა მეგალითური ნაგებობა?','დიდი ლოდებით','მხოლოდ ქაღალდით','მხოლოდ ქსოვილით','მხოლოდ მინით','მეგალითური ნაგებობები დიდი ზომის ქვებით შენდებოდა.'],['სად გვხვდება მრავალი ციკლოპური ნაგებობა?','სამხრეთ საქართველოში','მხოლოდ ეგვიპტის უდაბნოში','მხოლოდ სკანდინავიაში','მხოლოდ ამერიკაში','სამხრეთ საქართველოში, მათ შორის სამცხე-ჯავახეთში, მრავალი ასეთი ნაგებობაა.'],['რას ეწოდება ციტადელი?','ქალაქის ყველაზე გამაგრებულ ნაწილს','მხოლოდ ბაზრის დახლს','სარწყავ არხს','მდინარის შესართავს','ციტადელი დედაციხეა — ქალაქის ყველაზე დაცული ნაწილი.'],['როგორ უნდა შევაფასოთ ციხეების ციკლოპების მიერ აგების ამბავი?','როგორც მითოლოგიური წარმოდგენა','როგორც ფოტოთი დადასტურებული ფაქტი','როგორც თანამედროვე კანონი','როგორც ზუსტი თარიღი','ციკლოპების მიერ მშენებლობა მითია და ისტორიულ მტკიცებულებად არ ითვლება.'],['რას იცავდა მცირე სიმაგრეების ნაწილი?','სავაჭრო გზებს','მხოლოდ წიგნის გვერდებს','მხოლოდ მონეტის წარწერას','მხოლოდ გემის აფრას','ციკლოპური სიმაგრეების ნაწილი ძველ სავაჭრო გზებს იცავდა.']],
'მითი','ციკლოპები და ამირანის მიერ ციხეების აგება ხალხური წარმოდგენებია. რეალური მშენებლების ცოდნასა და შრომას არქეოლოგიური კვლევა გვაცნობს.');
add(14,4,'ქართველი ერის წარმოშობა, ანუ ეთნოგენეზი',72,'ხალხის ჩამოყალიბება ხანგრძლივი პროცესია. მის შესასწავლად სხვადასხვა მეცნიერების მონაცემებს ვადარებთ.',[
['საერთო ისტორია და კულტურა','ეთნოგენეზი ხალხის ჩამოყალიბების პროცესია. ერის ერთობას ისტორია, კულტურა, ენა, ტრადიციები და საერთო თვითშეგნება ქმნის. ეს ერთიანობა მრავალფეროვნებასაც მოიცავს.'],['მონათესავე ენები','ქართული, მეგრული, ლაზური და სვანური ქართველურ ენათა ოჯახს ეკუთვნის. მათი მსგავსება საერთო წარმოშობის შესწავლის მნიშვნელოვანი საფუძველია.'],['მტკიცებულება და გადმოცემა','ძველი მატიანეები ხალხთა წარმოშობის შესახებ თქმულებებსაც ინახავს. ასეთი მონათხრობი უნდა განვასხვავოთ ენათმეცნიერების, არქეოლოგიისა და სხვა კვლევების შედეგებისგან.']],
[['ეთნოგენეზი','ხალხის ჩამოყალიბების ხანგრძლივი პროცესი.'],['ქართველური ენები','მონათესავე ენების ოჯახი: ქართული, მეგრული, ლაზური და სვანური.'],['თვითშეგნება','ადამიანის ან ჯგუფის წარმოდგენა საკუთარ ვინაობასა და ერთობაზე.']],
[['რას ნიშნავს ეთნოგენეზი?','ხალხის ჩამოყალიბების პროცესს','მხოლოდ მონეტის მოჭრას','მხოლოდ ციხის დანგრევას','მხოლოდ კალენდრის ცვლილებას','ეთნოგენეზი ხალხის ჩამოყალიბების ხანგრძლივი პროცესია.'],['რომელი ენებია ქართველური?','ქართული, მეგრული, ლაზური, სვანური','ქართული, ბერძნული, ლათინური, სპარსული','სვანური, ეგვიპტური, არამეული, ბერძნული','ლათინური, მეგრული, სპარსული, არაბული','ქართველურ ენათა ოჯახში ქართული, მეგრული, ლაზური და სვანური შედის.'],['რა აერთიანებს ერს?','საერთო ისტორია, კულტურა და თვითშეგნება','მხოლოდ ერთნაირი სიმაღლე','მხოლოდ ერთი ხელობა','მხოლოდ ერთი ფერის სამოსი','ეროვნული ერთობისთვის მნიშვნელოვანია საერთო ისტორია, კულტურა და თვითშეგნება.'],['როგორ ვიკვლევთ ხალხის წარმოშობას?','სხვადასხვა მეცნიერების მონაცემთა შედარებით','ერთი თქმულების უპირობოდ მიღებით','მხოლოდ ნივთების ფერით','მხოლოდ სახელების დამთხვევით','ეთნოგენეზის კვლევა მრავალგვარი მტკიცებულების შედარებას მოითხოვს.'],['როგორ ვკითხულობთ მატიანის წარმოშობის თქმულებას?','როგორც შესაფასებელ ტრადიციას','როგორც თავისთავად საბოლოო მტკიცებულებას','როგორც თანამედროვე აღწერის შედეგს','როგორც ზუსტ არქეოლოგიურ გაზომვას','წარმოშობის თქმულება ისტორიული ტრადიციაა და სხვა მონაცემებით შემოწმებას საჭიროებს.']],
'ვარაუდი','საერთოქართველური ენის დაშლის ზუსტი თარიღები და არქეოლოგიური კულტურის კონკრეტულ ენასთან დაკავშირება სამეცნიერო რეკონსტრუქციებია. ისინი უპირობო ფაქტებად არ ისწავლება.');
add(15,5,'კოლხური კულტურა და კოლხას სამეფო',78,'კოლხურ ცულს შეეძლო ყოფილიყო სამუშაო იარაღიც, საბრძოლო ნივთიც და რიტუალის ნაწილიც.',[
['კოლხური კულტურა','კოლხური კულტურა დასავლეთ საქართველოში ჩამოყალიბდა და ფართო არეალზე გავრცელდა. მისი შესწავლისთვის მნიშვნელოვანია ლითონის ნივთები, ჭურჭელი და დასახლებები.'],['ერთი ნივთი — სხვადასხვა დანიშნულება','კოლხური ცული სამეურნეო, საბრძოლო და რიტუალურ საქმიანობაში გამოიყენებოდა. ნივთის ფორმა, შემკულობა და აღმოჩენის გარემო მისი დანიშნულების გარკვევაში გვეხმარება.'],['კოლხა წყაროებში','კოლხას შესახებ ცნობები ურარტულ წარწერებშიც გვხვდება. მეზობელ სახელმწიფოებთან ურთიერთობა და ომები ძველი წერილობითი წყაროების შედარებით იკვლევა.']],
[['კოლხური ცული','კოლხური კულტურისთვის დამახასიათებელი ბრინჯაოს ცული.'],['რიტუალი','გარკვეული წესით შესრულებული სიმბოლური მოქმედება.'],['ურარტუ','ვანის ტბის მიდამოებში არსებული ძველი სახელმწიფო.']],
[['სად ჩამოყალიბდა კოლხური კულტურის მთავარი კერა?','დასავლეთ საქართველოში','მხოლოდ ეგვიპტეში','მხოლოდ სკანდინავიაში','მხოლოდ ინდოეთში','კოლხური კულტურის მთავარი კერა დასავლეთ საქართველოში იყო.'],['რისგან მზადდებოდა კოლხური ცული?','ბრინჯაოსგან','ქაღალდისგან','ქსოვილისგან','ვულკანური ფერფლისგან','კოლხური ცული ბრინჯაოს იარაღია.'],['რომელი გამოყენება ჰქონდა კოლხურ ცულს?','სამეურნეო, საბრძოლო და რიტუალური','მხოლოდ დასაწერად','მხოლოდ საზომად','მხოლოდ საჭმლის შესანახად','კოლხურ ცულს რამდენიმე დანიშნულება ჰქონდა.'],['რომელი წყაროები გვაწვდის ცნობებს კოლხაზე?','ურარტული წარწერები','მხოლოდ თანამედროვე რომანები','მხოლოდ სატელეფონო ჩანაწერები','მხოლოდ პალეოლითური ბოჭკოები','ურარტული წარწერები კოლხას შესწავლის წერილობითი წყაროა.'],['სად მდებარეობდა ურარტუს მნიშვნელოვანი ცენტრი?','ვანის ტბის მიდამოებში','ბალტიის ზღვაზე','ატლანტის ოკეანეში','ავსტრალიაში','ურარტუს სამეფო ვანის ტბის რეგიონში იყო გაძლიერებული.']],
'მასწავლებლის შესამოწმებელი','კოლხას ადრეული თარიღები და მისი კავშირი მითურ აიეტთან წყაროთა ინტერპრეტაციას მოითხოვს. სამეფოს დაარსების ზუსტი წელი არ არის გამოგონილი.');
add(16,5,'კოლხური სამყარო და არგონავტების მითი',82,'იაზონი, მედეა და ოქროს საწმისი მითის გმირები და საგნებია. რას გვიამბობს მათი ამბავი ძველ სამყაროზე?',[
['მითის სიუჟეტი','მითის მიხედვით, იაზონი გემ „არგოთი“ კოლხეთში ოქროს საწმისის მოსაპოვებლად მოვიდა. კოლხი მეფის, აიეტის, ასული მედეა მას დაეხმარა. ეს ამბავი მითოლოგიურ მონათხრობს ეკუთვნის.'],['ბერძენი ავტორები','არგონავტების ამბავს სხვადასხვა ავტორი გადმოსცემს. განსაკუთრებით ვრცლად ის აპოლონიოს როდოსელის „არგონავტიკაშია“ მოთხრობილი.'],['რას ვიგებთ მითიდან?','მითი გვაცნობს ბერძნების წარმოდგენებს კოლხეთზე, მის სიმდიდრესა და შავ ზღვაზე მოგზაურობაზე. თუმცა ზღაპრული ამოცანები და ზებუნებრივი მოქმედებები ისტორიულ ფაქტებს არ ადასტურებს.']],
[['არგონავტი','მითში გემ „არგოს“ ეკიპაჟის წევრი.'],['მითი','ტრადიციული მონათხრობი გმირებზე, ღვთაებებსა და ზებუნებრივ მოვლენებზე.'],['ოქროს საწმისი','არგონავტების მითში ოქროსმატყლიანი ვერძის ტყავი.']],
[['რა ერქვა არგონავტების გემს მითში?','არგო','იბერია','თრიალეთი','სარკინე','მითში არგონავტები „არგოს“ ეკიპაჟის წევრები არიან.'],['ვინ ხელმძღვანელობდა მოგზაურობას მითის მიხედვით?','იაზონი','ფარნავაზი','კიროსი','სელევკოსი','არგონავტების მითში მოგზაურობის ხელმძღვანელი იაზონია.'],['ვინ დაეხმარა იაზონს მითში?','მედეა','სამარა','სერაფიტა','პტოლემე','მითის მიხედვით, იაზონს აიეტის ასული მედეა დაეხმარა.'],['რა ჟანრის მონათხრობია არგონავტების ამბავი?','მითოლოგიური','თანამედროვე სასამართლოს ოქმი','არქეოლოგიური გაზომვის ანგარიში','მოსახლეობის აღწერა','არგონავტების ამბავი მითია; მისი ყველა ეპიზოდი ისტორიულ ფაქტად ვერ ჩაითვლება.'],['რომელი ავტორის ნაწარმოებია „არგონავტიკა“?','აპოლონიოს როდოსელის','სტრაბონის','ვიტრუვიუსის','ლეონტი მროველის','„არგონავტიკა“ აპოლონიოს როდოსელის თხზულებაა.']],
'მითი','გემით მსგავსი მარშრუტის გავლა მოგზაურობის შესაძლებლობას აჩვენებს, მაგრამ იაზონისა და მედეას ყველა ამბის რეალურობას არ ამტკიცებს.',['დაასახელე მითის ერთი ზებუნებრივი დეტალი და ერთი საკითხი, რომლის რეალური მტკიცებულებით კვლევა შეიძლება.','ზებუნებრივი დეტალია ჯადოსნური დახმარება; კვლევადია შავი ზღვის სანაოსნო გზები და კოლხურ-ბერძნული სავაჭრო კავშირები.']);
add(17,5,'აღმოსავლეთ და სამხრეთ საქართველოს მოსახლეობის უძველესი გაერთიანებები',86,'ძველი მეზობლების წარწერებში ქვეყნების სახელები სხვადასხვაგვარადაა შემონახული.',[
['დიაოხი სხვადასხვა სახელით','სამხრეთ-დასავლეთის გაერთიანებას ასურული წყაროები დაიაენს, ურარტული — დიაოხს, ხოლო ბერძნული წყაროები ტაოხების მხარეს უკავშირებს. სახელთა დაკავშირებისას მკვლევრები ადგილმდებარეობასა და სხვა ცნობებსაც ითვალისწინებენ.'],['ძლიერი მეზობლები','დიაოხს ასურეთსა და ურარტუსთან დაპირისპირება უწევდა. მეფეთა წარწერები ლაშქრობებს, ხარკსა და მმართველებს ახსენებს. ისინი გამარჯვებული მხარის ხედვასაც გამოხატავს.'],['გაერთიანების მნიშვნელობა','ტომობრივი გაერთიანებები საერთო საფრთხესა და ეკონომიკურ კავშირებზე რეაგირებდა. აღმოსავლეთ და სამხრეთ საქართველოს ძველი ისტორიის აღსადგენად წერილობით და ნივთიერ მასალას ვადარებთ.']],
[['დიაოხი','უძველესი გაერთიანება საქართველოს ისტორიულ სამხრეთ-დასავლეთთან დაკავშირებულ სივრცეში.'],['ხარკი','დამორჩილებული ქვეყნის მიერ გადახდილი ვალდებულება.'],['ასურეთი','ძველი ახლო აღმოსავლეთის ძლიერი სახელმწიფო.']],
[['რა სახელით ახსენებენ ასურული წყაროები დიაოხთან დაკავშირებულ ქვეყანას?','დაიაენი','პტოლემეა','გალია','ათენი','ასურულ წყაროებში გვხვდება სახელწოდება დაიაენი.'],['რომელ წყაროებში გვხვდება სახელი დიაოხი?','ურარტულ წარწერებში','მხოლოდ თანამედროვე რეკლამაში','მხოლოდ ლათინურ ლექსებში','მხოლოდ რადიოჩანაწერებში','დიაოხის სახელი ურარტულ წარწერებშია შემონახული.'],['რომელი ძლიერი სახელმწიფოები ებრძოდნენ დიაოხს?','ასურეთი და ურარტუ','მხოლოდ რომი და საფრანგეთი','მხოლოდ ჩინეთი და იაპონია','მხოლოდ ათენი და კართაგენი','დიაოხს ასურეთსა და ურარტუსთან დაპირისპირება უწევდა.'],['რა არის ხარკი?','დამორჩილების ნიშნად გადასახდელი ვალდებულება','ქვის დასამუშავებელი იარაღი','მიწისქვეშა სამარხი','ახალი წელთაღრიცხვა','ხარკი დამორჩილებული მხარის მიერ გასაწევი ვალდებულებაა.'],['რატომ უნდა შევაფასოთ მეფის გამარჯვების წარწერა კრიტიკულად?','ის მეფის ინტერესსა და ხედვასაც გამოხატავს','ყველა წარწერა აუცილებლად გამოგონილია','ქვა ინფორმაციას ვერ ინახავს','ისტორიაში შედარება აკრძალულია','სამეფო წარწერები ავტორის პოლიტიკური მიზნების გათვალისწინებით უნდა წავიკითხოთ.']]);
add(18,5,'აქემენიანთა ირანი, ძველი ბერძნული კოლონიზაცია და საქართველო',90,'ძველი საქართველოს მოსახლეობა დიდ იმპერიებსა და ზღვით მოსულ ვაჭრებთან ურთიერთობდა.',[
['ბერძნული დასახლებები','ბერძნულმა კოლონიზაციამ შავი ზღვის სანაპიროებიც მოიცვა. სანაპირო დასახლებები ვაჭრობისა და კულტურული ურთიერთობის ცენტრები გახდა.'],['რას ცვლიდნენ?','კოლხეთში შემოდიოდა ბერძნული ჭურჭელი და სხვა ნაწარმი. გაჰქონდათ ადგილობრივი რესურსები და საქონელი. ვერცხლის მონეტა „კოლხური თეთრი“ აქტიური გაცვლის მნიშვნელოვანი ნიშანია.'],['ირანის გავლენა','აქემენიანთა ირანი დაყოფილი იყო სატრაპიებად, რომლებსაც სატრაპები მართავდნენ. მის გავლენაში ქართული ტომებით დასახლებული ტერიტორიების ნაწილიც მოექცა.']],
[['კოლონიზაცია','სხვა ტერიტორიაზე ახალი დასახლებების შექმნა.'],['სატრაპია','აქემენიანთა ირანის ადმინისტრაციული ერთეული.'],['კოლხური თეთრი','ძველ კოლხეთში მიმოქცევაში არსებული ვერცხლის მონეტა.']],
[['რომელ ზღვას უკავშირდება ბერძნული სანაპირო დასახლებები საქართველოში?','შავ ზღვას','ბალტიის ზღვას','წითელ ზღვას','არაბეთის ზღვას','ბერძნული სანაპირო დასახლებები შავიზღვისპირეთში შეიქმნა.'],['რა იყო კოლხური თეთრი?','ვერცხლის მონეტა','ქვის ცული','წარწერის ენა','სამეფო ეტლი','კოლხური თეთრი ვერცხლის მონეტაა და სავაჭრო ურთიერთობის ნიშანია.'],['რა ერქვა აქემენიანთა ირანის ადმინისტრაციულ ერთეულს?','სატრაპია','ციტადელი','ყორღანი','პალეოლითი','აქემენიანთა იმპერიის ადმინისტრაციულ ერთეულს სატრაპია ერქვა.'],['ვინ მართავდა სატრაპიას?','სატრაპი','მხოლოდ მეთუნე','მხოლოდ მემატიანე','მხოლოდ გემის მგზავრი','სატრაპიას სატრაპი მართავდა.'],['რას ადასტურებს უცხოური ჭურჭელი და მონეტები?','ვაჭრობასა და კავშირებს','ყველა კავშირის არარსებობას','მდინარის გაქრობას','დამწერლობის აუცილებელ აკრძალვას','უცხოური ნაწარმი და მონეტები სხვადასხვა მხარის ეკონომიკურ ურთიერთობაზე მეტყველებს.']]);
add(19,5,'მშენებლობა ძველ საქართველოში',94,'ქალაქების ადგილი და სახლების მასალა გარემოსა და ადამიანთა საჭიროებებს ერგებოდა.',[
['რატომ მდინარესთან?','მდინარის ნაპირები წყალსა და მიმოსვლის გზებს აერთიანებდა. მტკვრის გასწვრივ მდებარე მცხეთა, ურბნისი, უფლისციხე და სხვა ცენტრები ვაჭრობისა და ხელოსნობის განვითარებას უკავშირდებოდა.'],['მასალა გარემოდან','მშენებლები იყენებდნენ ქვას, ხესა და ალიზს. ალიზი ყალიბში მოთავსებული და მზეზე გამშრალი თიხის აგურია. რკინის იარაღი ქვის დამუშავებას აადვილებდა.'],['განსხვავებული სახლები','დასავლეთ საქართველოში ხის სახლები გავრცელდა. უფლისციხე კი კლდეში ნაკვეთი ქალაქის მაგალითია. სახლის ფორმასა და მასალაზე კლიმატიც ახდენდა გავლენას.']],
[['ალიზი','მზეზე გამშრალი თიხის აგური.'],['არქიტექტურა','შენობებისა და სივრცეების დაგეგმვისა და აგების ხელოვნება.'],['უფლისციხე','კლდეში ნაკვეთი ძველი ქალაქი შიდა ქართლში.']],
[['რა არის ალიზი?','მზეზე გამშრალი თიხის აგური','გამჭვირვალე მინა','ოქროს მონეტა','ქვის წარწერა','ალიზს თიხისგან ამზადებდნენ და მზეზე აშრობდნენ.'],['რომელი ქალაქია კლდეში ნაკვეთი?','უფლისციხე','ალექსანდრია','ათენი','ბაბილონი','უფლისციხე საქართველოს კლდეში ნაკვეთი ძველი ქალაქის მაგალითია.'],['რატომ ვითარდებოდა ქალაქები მდინარეებთან?','წყლისა და გზების სიახლოვის გამო','წყლისგან სრულად მოსაწყვეტად','ყველა ვაჭრის ასარიდებლად','ქვის გამოყენების ასაკრძალად','მდინარისპირა მდებარეობა წყლით მომარაგებასა და მიმოსვლას ამარტივებდა.'],['რომელი მასალა იყო გავრცელებული დასავლეთ საქართველოში?','ხე','მხოლოდ პლასტმასი','მხოლოდ ფოლადის ფურცელი','მხოლოდ ქაღალდი','დასავლეთ საქართველოში ხის მასალით მშენებლობა ფართოდ იყო გავრცელებული.'],['რას აადვილებდა რკინის იარაღი მშენებლობაში?','ქვის დამუშავებას','მდინარის შექმნას','საუკუნის დათვლას','მონეტაზე ენის შეცვლას','რკინის იარაღები ქვის მოპოვებასა და სასურველი ფორმის მიცემას აადვილებდა.']]);
add(20,6,'ალექსანდრე მაკედონელის იმპერიის დაშლა და დიადოხოსები',100,'ერთი დიდი იმპერიის დაშლამ საქართველოს მეზობლად ახალი სახელმწიფოები წარმოშვა.',[
['ალექსანდრეს იმპერია','ალექსანდრე მაკედონელმა დიდი ტერიტორია დაიპყრო და აქემენიანთა ირანი დაამარცხა. ის ძვ. წ. 323 წელს ბაბილონში გარდაიცვალა.'],['ვინ იყვნენ დიადოხოსები?','მისი გარდაცვალების შემდეგ სარდლები იმპერიის მემკვიდრეობისთვის იბრძოდნენ. მათ დიადოხოსები ეწოდათ. ერთიანი იმპერია რამდენიმე სახელმწიფოდ დაიშალა.'],['ელინისტური სამყარო','ამ სახელმწიფოებში ბერძნული და აღმოსავლური კულტურები ურთიერთქმედებდა. სელევკიდების სამეფო სელევკოსს, პტოლემეების ეგვიპტე კი პტოლემეს უკავშირდება.']],
[['დიადოხოსები','ალექსანდრეს მემკვიდრეობისთვის მებრძოლი სარდლები.'],['ელინიზმი','ბერძნული და აღმოსავლური კულტურების ურთიერთქმედებასთან დაკავშირებული ეპოქა.'],['იმპერია','სახელმწიფო, რომელიც მრავალ ხალხსა და დიდ ტერიტორიას მოიცავს.']],
[['როდის გარდაიცვალა ალექსანდრე მაკედონელი?','ძვ. წ. 323 წელს','ახ. წ. 323 წელს','ძვ. წ. 1112 წელს','ახ. წ. 1991 წელს','ალექსანდრე ძვ. წ. 323 წელს ბაბილონში გარდაიცვალა.'],['ვის ეწოდათ დიადოხოსები?','ალექსანდრეს მემკვიდრეობისთვის მებრძოლ სარდლებს','კოლხ მეთუნეებს','დმანისის ჰომინინებს','მხოლოდ რომაელ გეოგრაფებს','დიადოხოსები ალექსანდრეს სარდლები და მისი მემკვიდრეობისთვის მებრძოლები იყვნენ.'],['რა მოუვიდა იმპერიას ალექსანდრეს სიკვდილის შემდეგ?','რამდენიმე სახელმწიფოდ დაიშალა','ერთ უცვლელ სახელმწიფოდ დარჩა საუკუნეებით','ზღვაში ჩაიძირა','ყველა ქალაქი ერთ დღეში გაქრა','ალექსანდრეს გარდაცვალების შემდეგ მისი იმპერია დაიშალა.'],['ვის უკავშირდება პტოლემეების ეგვიპტე?','პტოლემეს','ფარნავაზს','ქუჯის','აიეტს','პტოლემე ალექსანდრეს ერთ-ერთი სარდალი და ეგვიპტის დინასტიის დამაარსებელი იყო.'],['რა ახასიათებს ელინისტურ სამყაროს?','ბერძნული და აღმოსავლური კულტურების ურთიერთქმედება','ყველა კულტურული კავშირის აკრძალვა','დამწერლობის სრული გაქრობა','მხოლოდ ქვის იარაღის არსებობა','ელინისტურ სამყაროში ბერძნული და აღმოსავლური კულტურები ურთიერთქმედებდა.']],
'ვარაუდი','ალექსანდრეს სიკვდილის ზუსტი მიზეზი ბოლომდე დადგენილი არ არის. მოწამვლა მხოლოდ ერთ-ერთი ვარაუდია.');
add(21,6,'ფარნავაზი და აზო',104,'ქართლის სამეფოს დასაწყისის შესახებ ორი ქართული წყარო განსხვავებულ ცნობებს გვთავაზობს.',[
['ორი წყარო','„მოქცევაი ქართლისაი“ და „ქართლის ცხოვრება“ ქართლის ადრეულ მმართველებზე მოგვითხრობს. აზოს წარმომავლობისა და როლის გადმოცემა მათში განსხვავდება.'],['ფარნავაზის ამბავი','„ქართლის ცხოვრება“ ფარნავაზს მცხეთის წარჩინებულ ოჯახს უკავშირებს. ტექსტში გვხვდება ბავშვობის, სიზმრისა და ნაპოვნი განძის ეპიზოდები. ეს მატიანის მონათხრობია.'],['როგორ გავარჩიოთ?','ალექსანდრეს საქართველოში პირადად ლაშქრობა ისტორიულად არ დასტურდება. წყაროში ასეთი ცნობის არსებობა თავისთავად მოვლენის რეალურობას არ ამტკიცებს.']],
[['საისტორიო ტრადიცია','წარსულის შესახებ გადმოცემათა ერთობლიობა.'],['მამასახლისი','აქ: თემის ან ქალაქის მმართველი.'],['წყაროს კრიტიკა','ცნობის წარმოშობის, მიზნისა და სანდოობის შეფასება.']],
[['რომელი ორი წყარო მოგვითხრობს ქართლის ადრეულ მმართველებზე?','მოქცევაი ქართლისაი და ქართლის ცხოვრება','ილიადა და არგონავტიკა','მხოლოდ თანამედროვე გაზეთი','მხოლოდ არქეოლოგიური ფოტო','ქართლის ადრეულ ისტორიას „მოქცევაი ქართლისაი“ და „ქართლის ცხოვრება“ აღწერს.'],['როგორია აზოს შესახებ წყაროთა ცნობები?','ზოგიერთ საკითხში განსხვავებული','ყველა სიტყვით ერთნაირი','საერთოდ არ არსებობს','მხოლოდ მონეტაზეა მოცემული','აზოს წარმომავლობასა და როლს ქართული წყაროები განსხვავებულად გადმოსცემს.'],['როგორ უნდა წავიკითხოთ ფარნავაზის სიზმრის ამბავი?','როგორც მატიანის მონათხრობი','როგორც არქეოლოგიური გაზომვა','როგორც თანამედროვე ფოტო','როგორც მოსახლეობის აღწერა','სიზმრისა და განძის ეპიზოდები მატიანის თხრობითი ტრადიციის ნაწილია.'],['როგორ შევაფასოთ ალექსანდრეს პირადად საქართველოში ლაშქრობა?','ისტორიულად არ დასტურდება','ფოტოებითაა დადასტურებული','დმანისის ყბითაა დადასტურებული','ყველა წყარო ზუსტ თარიღს გვაძლევს','ალექსანდრე მაკედონელის საქართველოში პირადად ლაშქრობა ისტორიულად არ დასტურდება.'],['რას გულისხმობს წყაროს კრიტიკა?','ცნობის სანდოობის შეფასებას','ყველა წყაროს წაშლას','ნებისმიერი მითის ფაქტად გამოცხადებას','მხოლოდ მართლწერის შემოწმებას','წყაროს კრიტიკა ცნობის წარმოშობისა და სანდოობის შეფასებაა.']],
'მასწავლებლის შესამოწმებელი','აზო და აზონი სხვადასხვა წყაროში განსხვავებული სახით გვხვდება. აპლიკაცია ამ განსხვავებას ინარჩუნებს და გადმოცემებს ერთ უტყუარ ბიოგრაფიად არ აერთიანებს.');
add(22,6,'ქართლის სამეფოს შექმნა',108,'მატიანის მიხედვით, ფარნავაზის წარმატება მოკავშირეების მოძიებასა და გაერთიანებას უკავშირდებოდა.',[
['ფარნავაზი და ქუჯი','„ქართლის ცხოვრების“ მონათხრობში ფარნავაზი დასავლეთ საქართველოს მმართველ ქუჯის უკავშირდება. ისინი აზოს წინააღმდეგ ერთობლივ მოქმედებას გეგმავენ.'],['მოკავშირეები','წყარო ჩრდილოეთ კავკასიელი მოკავშირეების დახმარებასაც ახსენებს. სამხედრო ძალისა და რესურსების გაერთიანება ბრძოლის შედეგზე მოქმედებდა.'],['სახელმწიფოს სათავეები','ქართული საისტორიო ტრადიცია ქართლის სამეფოს ჩამოყალიბებას ფარნავაზს უკავშირებს. ადრეული მოვლენების ზუსტი ქრონოლოგია და დეტალები კვლევისა და წყაროთა შედარების საგანია.']],
[['მოკავშირე','საერთო მიზნისთვის თანამშრომელი მხარე.'],['ქართლის სამეფო','ძველი აღმოსავლურქართული სახელმწიფო, რომელსაც იბერიასაც უწოდებდნენ.'],['გაერთიანება','საერთო ძალისა და რესურსების შეკრება.']],
[['ვის სთხოვა ფარნავაზმა დახმარება მატიანის მიხედვით?','ქუჯის','ვიტრუვიუსს','ჰომეროსს','ბესას','„ქართლის ცხოვრების“ მიხედვით, ფარნავაზის მთავარი მოკავშირე ქუჯი გახდა.'],['ვის წინააღმდეგ ერთიანდებიან ისინი წყაროს მონათხრობში?','აზოს წინააღმდეგ','დმანისელი ჰომინინების წინააღმდეგ','აპოლონიოსის წინააღმდეგ','ქსენოფონტის წინააღმდეგ','მატიანე ფარნავაზისა და ქუჯის აზოს წინააღმდეგ მოქმედებაზე მოგვითხრობს.'],['რას ნიშნავს მოკავშირე?','საერთო მიზნისთვის თანამშრომელ მხარეს','მხოლოდ ოჯახის უფროსს','მხოლოდ მეთუნეს','ნებისმიერ მდინარეს','მოკავშირეები საერთო მიზნის მისაღწევად თანამშრომლობენ.'],['რას უწყობდა ხელს გაერთიანება?','ძალისა და რესურსების გაზრდას','ყველა კავშირის გაწყვეტას','დახმარების შეუძლებლობას','გზების გაქრობას','მოკავშირეთა გაერთიანება სამხედრო ძალასა და რესურსებს ზრდიდა.'],['ვის უკავშირებს ქართული ტრადიცია ქართლის სამეფოს ჩამოყალიბებას?','ფარნავაზს','კიროსს','ჰომეროსს','იაზონს','ქართული საისტორიო ტრადიცია ქართლის სამეფოს ჩამოყალიბებას ფარნავაზს უკავშირებს.']],
'ვარაუდი','ბრძოლის დეტალები და ფარნავაზის ცხოვრების ამბები მოგვიანო წერილობით ტრადიციაშია დაცული. ზუსტი თარიღები ყველა ცნობასთან ერთნაირად მტკიცედ დადგენილი არ არის.');
add(23,6,'ფარნავაზის მიერ ქართლის სახელმწიფოებრივი მოწყობა',112,'სამეფოს მართვას სჭირდებოდა მხარეების ორგანიზება, მმართველები და საერთო წესები.',[
['სამეფოს დაყოფა','„ქართლის ცხოვრების“ მიხედვით, ფარნავაზმა ქვეყანა საერისთავოებად დაყო. მხარეებს ერისთავები მართავდნენ, სამხედრო ორგანიზებაში კი სპასპეტი მონაწილეობდა.'],['საერთო ცენტრი','მატიანე ფარნავაზის საქმიანობას სახელმწიფოს განმტკიცებას, საერთო ენის მნიშვნელობასა და არმაზის კულტის დამკვიდრებას უკავშირებს. ეს ცნობები წყაროს ტრადიციას ასახავს.'],['ანბანის შესახებ ცნობა','მატიანე ფარნავაზს ქართული მწიგნობრობის გავრცელებასაც მიაწერს. ქართული ანბანის წარმოშობის ზუსტი საკითხი ცალკე კვლევის საგანია; მატიანის ცნობა და შემორჩენილი წარწერა ერთი ტიპის მტკიცებულება არ არის.']],
[['ერისთავი','მხარის მმართველი და სამხედრო ხელმძღვანელი.'],['საერისთავო','ერისთავის სამართავი ტერიტორია.'],['სპასპეტი','ლაშქრის უმაღლესი ხელმძღვანელი ძველ ქართულ სახელმწიფოებრივ წყობაში.']],
[['რას ეწოდებოდა ერისთავის სამართავი მხარე?','საერისთავო','სატრაპის მონეტა','ყორღანი','პეტროგლიფი','საერისთავო ერისთავის სამართავი ტერიტორია იყო.'],['ვინ იყო ერისთავი?','მხარის მმართველი','მხოლოდ გემის მშენებელი','მხოლოდ ოქრომჭედელი','მხოლოდ მემატიანე','ერისთავი მხარის მმართველი და სამხედრო ხელმძღვანელი იყო.'],['რა ფუნქცია უკავშირდება სპასპეტს?','ლაშქრის ხელმძღვანელობა','მხოლოდ ყურძნის დაწურვა','მხოლოდ ჭურჭლის გამოწვა','მხოლოდ ქვის გახეხვა','სპასპეტი ლაშქრის უმაღლეს ხელმძღვანელობას უკავშირდება.'],['რომელი წყარო გვაწვდის ამ ცნობებს ფარნავაზის რეფორმებზე?','ქართლის ცხოვრება','მხოლოდ არგონავტიკა','მხოლოდ ვიტრუვიუსის სახლის ნახაზი','მხოლოდ კოლხური ცული','ფარნავაზის სახელმწიფოებრივი მოწყობის შესახებ ძირითადად „ქართლის ცხოვრება“ გვიამბობს.'],['როგორ შევაფასოთ მატიანის ცნობა ანბანის შესახებ?','შევადაროთ სხვა მტკიცებულებებს','ზუსტად დათარიღებულ წარწერას გავუტოლოთ','მხოლოდ სიზმრად მივიჩნიოთ','ყველა კვლევა შევწყვიტოთ','ანბანის შესახებ მატიანის ცნობა სხვა მონაცემებთან შედარებას მოითხოვს.']],
'მასწავლებლის შესამოწმებელი','ანბანის შექმნის ფარნავაზისთვის მიწერა მატიანის ტრადიციაა. ეს განსხვავდება არქეოლოგიურად შემორჩენილი ქართული წარწერების დათარიღებისგან.');
add(24,6,'რა ვიცით ქართლის სამეფოს შესახებ',116,'მცხეთის გზები, სიმაგრეები და მოსახლეობა ძველი ქართლის ცხოვრების გასაგებად მნიშვნელოვანი გასაღებია.',[
['რატომ მცხეთა?','მცხეთა მნიშვნელოვანი გზების გადაკვეთაზე მდებარეობდა. მტკვრისა და არაგვის ხეობები სხვადასხვა მხარეს აკავშირებდა, ვაჭრობა კი ქალაქის განვითარებას უწყობდა ხელს.'],['ქალაქის დაცვა','მცხეთის გზებსა და მისადგომებს სიმაგრეები აკონტროლებდა. მათ შორის იყო არმაზციხე და ზადენციხე. ხელსაყრელი მდებარეობა დაცვასა და მიმოსვლას ერთდროულად ემსახურებოდა.'],['სამეფო და საზოგადოება','ქართლი მონარქიული სახელმწიფო იყო — სათავეში მეფე იდგა. საზოგადოებაში სხვადასხვა მდგომარეობისა და საქმიანობის ადამიანები ცხოვრობდნენ. ცნობებს ბერძენი გეოგრაფი სტრაბონიც გვაწვდის.']],
[['მონარქია','მმართველობის ფორმა, რომლის სათავეშიც მონარქი დგას.'],['სეფეწული','სამეფო საგვარეულოს წარმომადგენელი.'],['სტრაბონი','ძველი ბერძენი გეოგრაფი, რომელიც ქართლზეც წერდა.']],
[['რა იყო ქართლის სამეფოს დედაქალაქი?','მცხეთა','ათენი','ბაბილონი','ალექსანდრია','ქართლის სამეფოს დედაქალაქი მცხეთა იყო.'],['რა უწყობდა ხელს მცხეთის განვითარებას?','მნიშვნელოვანი გზების გადაკვეთა','ყველა გზისგან მოშორება','წყლის არარსებობა','ვაჭრობის აკრძალვა','მცხეთის გეოგრაფიული მდებარეობა ვაჭრობასა და ქალაქის განვითარებას უწყობდა ხელს.'],['რომელი სიმაგრე უკავშირდება მცხეთის დაცვას?','არმაზციხე','მხოლოდ რომის კოლიზეუმი','მხოლოდ ათენის აკროპოლისი','მხოლოდ ბაბილონის კოშკი','არმაზციხე მცხეთისა და მისი გზების დაცვას უკავშირდებოდა.'],['რა მმართველობის ფორმა ჰქონდა ქართლის სამეფოს?','მონარქია','თანამედროვე რესპუბლიკა','სკოლის თვითმმართველობა','მხოლოდ ვაჭართა კლუბი','ქართლის სამეფოს სათავეში მეფე იდგა.'],['რომელი ბერძენი ავტორი გვაწვდის ცნობებს ქართლზე?','სტრაბონი','მხოლოდ მედეა','მხოლოდ სამარა','მხოლოდ ქუჯი','სტრაბონის ცნობები ქართლის სამეფოს შესწავლის მნიშვნელოვანი წყაროა.']]);
add(25,6,'ქართლის სამეფო ფარნავაზ მეფის მემკვიდრეების დროს',120,'სამეფოს შენარჩუნება მეზობელ სახელმწიფოებთან ურთიერთობასა და შიდა განმტკიცებას მოითხოვდა.',[
['ცვალებადი სამყარო','ფარნავაზის მემკვიდრეებს მეზობელი სახელმწიფოების გაძლიერება და დასუსტება უნდა გაეთვალისწინებინათ. მეგობრობა და სამხედრო წინააღმდეგობა პოლიტიკური გარემოს მიხედვით იცვლებოდა.'],['სელევკიდები და რომი','ქართლის ადრეული ურთიერთობები სელევკიდების სამეფოსაც უკავშირდება. მოგვიანებით სელევკიდები დასუსტდნენ, რომის გავლენა კი აღმოსავლეთით გაფართოვდა.'],['მშენებლობა და დაცვა','ქართული მატიანეები ფარნავაზის მემკვიდრეთა დროს ციხე-ქალაქების მშენებლობასა და განმტკიცებას ახსენებს. ჩრდილოეთ კავკასიასთან კავშირიც უსაფრთხოების მნიშვნელოვანი ნაწილი იყო.']],
[['დინასტია','მმართველთა საგვარეულო, რომლის წევრებიც ერთმანეთს ენაცვლებიან.'],['დიპლომატია','სახელმწიფოთა ურთიერთობისა და მოლაპარაკების საქმიანობა.'],['მემკვიდრე','პირი, რომელიც წინამორბედის უფლებას ან ხელისუფლებას იღებს.']],
[['რატომ იყო მეზობლების მდგომარეობის გათვალისწინება საჭირო?','სამეფოს უსაფრთხოებისა და ინტერესების დასაცავად','მხოლოდ ასოების ფორმის შესაცვლელად','მდინარეების გასაქრობად','მეურნეობის შესაწყვეტად','მეზობელთა ძალთა ცვლილება ქართლის უსაფრთხოებასა და პოლიტიკაზე მოქმედებდა.'],['რა ეწოდება მმართველთა საგვარეულოს?','დინასტია','კერამიკა','ეპიგრაფიკა','ყორღანი','დინასტია მმართველთა საგვარეულოა.'],['რა ხდებოდა სელევკიდების დასუსტების ფონზე?','რომის გავლენა აღმოსავლეთით ფართოვდებოდა','რომი საერთოდ არ არსებობდა','მთელი მსოფლიო ერთ ქალაქად იქცა','ყველა გზას მნიშვნელობა დაეკარგა','სელევკიდების დასუსტების პერიოდში რომი აღმოსავლეთით გავლენას აფართოებდა.'],['რას ახსენებს მატიანე მემკვიდრე მეფეთა საქმიანობაში?','ციხე-ქალაქების მშენებლობასა და განმტკიცებას','კომპიუტერების აწყობას','რკინიგზის ელექტრიფიკაციას','თვითმფრინავების წარმოებას','მატიანეები ფარნავაზის მემკვიდრეთა დროს აღმშენებლობასა და თავდაცვას ახსენებს.'],['რა არის დიპლომატია?','სახელმწიფოთა ურთიერთობა და მოლაპარაკება','მხოლოდ ლითონის ჩამოსხმა','მხოლოდ მიწის გათხრა','მხოლოდ დროის გაზომვა','დიპლომატია სხვა სახელმწიფოებთან ურთიერთობისა და მოლაპარაკების გზაა.']],
'მასწავლებლის შესამოწმებელი','წიგნის 121-ე გვერდზე ანტიოქოს I სელევკიდების „ფუძემდებლად“ არის მოხსენიებული, მაშინ როცა მე-20 პარაგრაფში დამაარსებლად სელევკოს I სახელდება. აპლიკაციაში დამაარსებლად სელევკოს I არის მითითებული; წინააღმდეგობა მასწავლებლისთვის მონიშნულია.');
